// Without equals/hashCode override - BAD
record Order(Long id, String item) {} // records auto-generate equals/hashCode - GOOD

class BadCustomer {
    private Long id;
    private String name;
    // No equals/hashCode override - uses Object's identity comparison
}

var customers = new HashSet<BadCustomer>();
var customer1 = new BadCustomer();
customer1.id = 1L;
customer1.name = "Alice";
var customer2 = new BadCustomer();
customer2.id = 1L;  // Same ID
customer2.name = "Alice";  // Same name

customers.add(customer1);
customers.add(customer2);  // Both added!
System.out.println(customers.size());  // Prints 2 - duplicates allowed

// With proper equals/hashCode or using record - GOOD
var orders = new HashSet<Order>();
orders.add(new Order(1L, "Laptop"));
orders.add(new Order(1L, "Laptop"));  // Duplicate rejected
System.out.println(orders.size());  // Prints 1 - correct behavior

var activeUsers = new HashSet<>(Set.of("Alice", "Bob", "Charlie", "Diana"));
var premiumUsers = new HashSet<>(Set.of("Bob", "Diana", "Eve"));

// Union - combines both sets (mutates activeUsers)
var unionSet = new HashSet<>(activeUsers);  // Make a copy first
unionSet.addAll(premiumUsers);
System.out.println("Union: " + unionSet);  // [Alice, Bob, Charlie, Diana, Eve]

// Intersection - keeps only common elements (mutates activeUsers copy)
var intersectionSet = new HashSet<>(activeUsers);
intersectionSet.retainAll(premiumUsers);  // Keeps only Bob, Diana
System.out.println("Intersection: " + intersectionSet);  // [Bob, Diana]

// Difference - removes premiumUsers from activeUsers (mutates copy)
var differenceSet = new HashSet<>(activeUsers);
differenceSet.removeAll(premiumUsers);  // Removes Bob, Diana
System.out.println("Difference: " + differenceSet);  // [Alice, Charlie]

// Immutable approach with Streams (Java 8+)
var immutableUnion = Stream.concat(activeUsers.stream(), premiumUsers.stream())
    .collect(Collectors.toSet());
var immutableIntersection = activeUsers.stream()
    .filter(premiumUsers::contains)
    .collect(Collectors.toSet());
